def data(root=""):
    """The raw PAL8 pixels: a memoryview into XIP flash when the ROMFS asset region is
    mounted (0-copy; slicing stays 0-copy), else the sibling .bin read into RAM."""
    try:
        return memoryview(open("/rom/" + BIN, "rb"))
    except OSError:
        with open(root + BIN, "rb") as f:
            return f.read()


def bitmap(pg, root=""):
    return pg.Bitmap(data(root), W, H, format=pg.PAL8, palette=PAL,
                     frames=FRAMES, stride=STRIDE, transparent=TRANSP)
